	LOC_BGD_CONGRES_REVOTER_AIDE = { en_US = "Cancel your end of turn to change your votes. Possible while you have time left and another player is still voting.", fr_FR = "Annulez votre fin de tour pour modifier vos votes. Possible tant qu'il vous reste du temps et qu'un autre joueur vote encore.", de_DE = "Nimmt Ihr Rundenende zurück, um Ihre Stimmen zu ändern. Möglich, solange Ihnen Zeit bleibt und ein anderer Spieler noch abstimmt.", es_ES = "Anula el fin de tu turno para cambiar tus votos. Posible mientras te quede tiempo y otro jugador siga votando.", it_IT = "Annulla la fine del tuo turno per cambiare i tuoi voti. Possibile finché ti resta tempo e un altro giocatore sta ancora votando.", ja_JP = "ターン終了を取り消して投票を変更します。残り時間があり、他のプレイヤーがまだ投票中の場合に可能です。", ko_KR = "턴 종료를 취소하고 투표를 변경합니다. 남은 시간이 있고 다른 플레이어가 아직 투표 중일 때 가능합니다.", pl_PL = "Cofnij zakończenie tury, aby zmienić głosy. Możliwe, dopóki masz jeszcze czas, a inny gracz nadal głosuje.", pt_BR = "Cancele o fim do seu turno para mudar seus votos. Possível enquanto houver tempo e outro jogador ainda estiver votando.", ru_RU = "Отменить завершение хода, чтобы изменить голоса. Возможно, пока у вас осталось время и другой игрок ещё голосует.", zh_Hans_CN = "取消回合结束以修改投票。仅在您仍有剩余时间且其他玩家仍在投票时可用。" },
	LOC_BGD_CONGRES_SPECTATEUR = { en_US = "Spectator: read only, your votes are not counted.", fr_FR = "Spectateur : consultation seule, vos votes ne comptent pas.", de_DE = "Zuschauer: nur ansehen, Ihre Stimmen zählen nicht.", es_ES = "Espectador: solo consulta, tus votos no cuentan.", it_IT = "Spettatore: sola consultazione, i tuoi voti non contano.", ja_JP = "観戦者: 閲覧のみで、投票は数えられません。", ko_KR = "관전자: 보기만 가능하며, 투표는 집계되지 않습니다.", pl_PL = "Obserwator: tylko podgląd, twoje głosy się nie liczą.", pt_BR = "Espectador: apenas consulta, seus votos não contam.", ru_RU = "Зритель: только просмотр, ваши голоса не учитываются.", zh_Hans_CN = "观战者：仅可查看，你的投票不计入。" },
	LOC_BGD_DEBORDEMENT = { en_US = "+{1} [ICON_Production] in reserve, added to next turn's production (at most one turn of production).", fr_FR = "+{1} [ICON_Production] en réserve, ajoutés à la production du prochain tour (au plus un tour de production).", de_DE = "+{1} [ICON_Production] in Reserve, kommen zur Produktion der nächsten Runde hinzu (höchstens eine Runde Produktion).", es_ES = "+{1} [ICON_Production] en reserva, que se suman a la producción del próximo turno (como máximo un turno de producción).", it_IT = "+{1} [ICON_Production] in riserva, aggiunti alla produzione del prossimo turno (al massimo un turno di produzione).", ja_JP = "+{1} [ICON_Production] を保持中。次のターンの生産力に加算されます (最大 1 ターン分の生産力)。", ko_KR = "+{1} [ICON_Production] 비축, 다음 턴 생산에 더해집니다 (최대 1턴의 생산력).", pl_PL = "+{1} [ICON_Production] w zapasie, doliczane do produkcji w następnej turze (najwyżej jedna tura produkcji).", pt_BR = "+{1} [ICON_Production] em reserva, somados à produção do próximo turno (no máximo um turno de produção).", ru_RU = "+{1} [ICON_Production] в запасе, добавятся к производству следующего хода (не больше одного хода производства).", zh_Hans_CN = "储备 +{1} [ICON_Production]，将加到下一回合的生产中（最多一回合的生产力）。" },
	LOC_BGD_DEPART_FIN_HOTE = { en_US = "turn over: the host's turn timer ran out.", fr_FR = "fin du tour : le minuteur de l'hôte est écoulé.", de_DE = "Runde vorbei: Der Timer des Hosts ist abgelaufen.", es_ES = "fin del turno: el temporizador del anfitrión ha terminado.", it_IT = "fine del turno: il timer dell'host è scaduto.", ja_JP = "ターン終了: ホストのタイマーが切れました。", ko_KR = "턴 종료: 호스트의 타이머가 끝났습니다.", pl_PL = "koniec tury: zegar hosta dobiegł końca.", pt_BR = "fim do turno: o cronômetro do anfitrião acabou.", ru_RU = "конец хода: таймер хоста истёк.", zh_Hans_CN = "回合结束：主机的计时器已到。" },
