	LOC_BGD_DEPART_PARTI = { en_US = "go!", fr_FR = "c'est parti !", de_DE = "Los!", es_ES = "¡adelante!", it_IT = "via!", ja_JP = "スタート!", ko_KR = "시작!", pl_PL = "start!", pt_BR = "vai!", ru_RU = "поехали!", zh_Hans_CN = "开始！" },
	LOC_BGD_DEPART_SANS = { en_US = "started without {1} (not ready after {2} s).", fr_FR = "départ donné sans {1} (pas prêts après {2} s).", de_DE = "ohne {1} gestartet (nach {2} s nicht bereit).", es_ES = "turno iniciado sin {1} (no estaban listos tras {2} s).", it_IT = "turno avviato senza {1} (non pronti dopo {2} s).", ja_JP = "{1} を待たずに開始しました ({2} 秒経っても準備ができていません)。", ko_KR = "{1} 없이 시작했습니다({2}초 후에도 준비되지 않음).", pl_PL = "rozpoczęto bez: {1} (niegotowi po {2} s).", pt_BR = "turno iniciado sem {1} (não estavam prontos após {2} s).", ru_RU = "ход начат без: {1} (не готовы через {2} с).", zh_Hans_CN = "已在没有 {1} 的情况下开始（{2} 秒后仍未准备好）。" },
	LOC_BGD_IMHOTEP_EFFET = { en_US = "Grants {1} [ICON_Production] Production towards wonder construction, {2} if the wonder is from the Ancient or Classical Era.", fr_FR = "[ICON_Production] Production +{1} pour la construction de merveilles, portée à {2} si la merveille est de l'Antiquité ou de l'ère classique.", de_DE = "Gewährt {1} [ICON_Production] Produktion für den Bau von Weltwundern, {2}, wenn das Weltwunder aus der Antike oder der Klassik stammt.", es_ES = "Otorga {1} de [ICON_Production] producción para la construcción de maravillas, {2} si la maravilla es de la Era Antigua o Clásica.", it_IT = "Fornisce {1} [ICON_Production] Produzione per la costruzione di meraviglie, {2} se la meraviglia appartiene all'Era Antica o Classica.", ja_JP = "遺産の建造に [ICON_Production] 生産力+{1}。古代または古典時代の遺産の場合は+{2}。", ko_KR = "불가사의 건설에 [ICON_Production] 생산력 +{1}. 고대 또는 고전 시대 불가사의라면 +{2}.", pl_PL = "Zapewnia {1} pkt. [ICON_Production] produkcji na budowę cudu, {2}, jeśli cud pochodzi z ery starożytnej lub klasycznej.", pt_BR = "Concede {1} de [ICON_Production] Produção para a construção de maravilhas, {2} se a maravilha for da Era Antiga ou Clássica.", ru_RU = "Дает {1} ед. [ICON_Production] производства для строительства чуда, {2}, если чудо относится к Древнему миру или Античности.", zh_Hans_CN = "为奇观建造提供 {1} [ICON_Production] 生产力，若为远古或古典时代的奇观则为 {2}。" },
	LOC_BGD_MAJ_BOUTON_MAJ = { en_US = "Update", fr_FR = "Mettre à jour", de_DE = "Aktualisieren", es_ES = "Actualizar", it_IT = "Aggiorna", ja_JP = "アップデート", ko_KR = "업데이트", pl_PL = "Aktualizuj", pt_BR = "Atualizar", ru_RU = "Обновить", zh_Hans_CN = "更新" },
	LOC_BGD_MAJ_BOUTON_PLUS_TARD = { en_US = "Later", fr_FR = "Plus tard", de_DE = "Später", es_ES = "Más tarde", it_IT = "Più tardi", ja_JP = "後で", ko_KR = "나중에", pl_PL = "Później", pt_BR = "Mais tarde", ru_RU = "Позже", zh_Hans_CN = "稍后" },
	LOC_BGD_MAJ_PAGE = { en_US = "The BetterGameExperience installer was not found: the latest release page has opened in the browser.", fr_FR = "L'installeur de BetterGameExperience est introuvable : la page de la dernière version s'est ouverte dans le navigateur.", de_DE = "Das Installationsprogramm von BetterGameExperience wurde nicht gefunden: Die Seite der neuesten Version wurde im Browser geöffnet.", es_ES = "No se ha encontrado el instalador de BetterGameExperience: la página de la última versión se ha abierto en el navegador.", it_IT = "Programma di installazione di BetterGameExperience non trovato: la pagina dell'ultima versione è stata aperta nel browser.", ja_JP = "BetterGameExperience のインストーラーが見つかりません。最新リリースのページをブラウザで開きました。", ko_KR = "BetterGameExperience 설치 프로그램을 찾을 수 없습니다. 최신 릴리스 페이지를 브라우저에서 열었습니다.", pl_PL = "Nie znaleziono instalatora BetterGameExperience: strona najnowszej wersji została otwarta w przeglądarce.", pt_BR = "O instalador do BetterGameExperience não foi encontrado: a página da versão mais recente foi aberta no navegador.", ru_RU = "Установщик BetterGameExperience не найден: страница последнего выпуска открыта в браузере.", zh_Hans_CN = "找不到 BetterGameExperience 安装程序：已在浏览器中打开最新版本的页面。" },
	LOC_BGD_MAJ_TEXTE_PRERELEASE = { en_US = "BetterGameExperience pre-release {1} is available (installed: {2}).[NEWLINE][NEWLINE]This is a test version: you get it because the \"Pre-release\" box is ticked in the installer.[NEWLINE][NEWLINE]\"Update\" closes the game and starts the installer.", fr_FR = "La pré-release {1} de BetterGameExperience est disponible (installée : {2}).[NEWLINE][NEWLINE]C'est une version de test : vous la recevez parce que la case « Pré-release » est cochée dans l'installeur.[NEWLINE][NEWLINE]« Mettre à jour » ferme le jeu et lance l'installeur.", de_DE = "BetterGameExperience-Vorabversion {1} ist verfügbar (installiert: {2}).[NEWLINE][NEWLINE]Dies ist eine Testversion: Sie erhalten sie, weil im Installationsprogramm das Kästchen „Vorabversion“ angehakt ist.[NEWLINE][NEWLINE]„Aktualisieren“ schließt das Spiel und startet das Installationsprogramm.", es_ES = "La versión preliminar {1} de BetterGameExperience está disponible (instalada: {2}).[NEWLINE][NEWLINE]Es una versión de prueba: la recibes porque la casilla «Versión preliminar» está marcada en el instalador.[NEWLINE][NEWLINE]«Actualizar» cierra el juego e inicia el instalador.", it_IT = "La versione di prova {1} di BetterGameExperience è disponibile (installata: {2}).[NEWLINE][NEWLINE]È una versione di test: la ricevi perché la casella \"Versione di prova\" è spuntata nel programma di installazione.[NEWLINE][NEWLINE]\"Aggiorna\" chiude il gioco e avvia il programma di installazione.", ja_JP = "BetterGameExperience のプレリリース {1} が利用可能です (インストール済み: {2})。[NEWLINE][NEWLINE]これはテスト版です。インストーラーで「プレリリース」にチェックが入っているため届いています。[NEWLINE][NEWLINE]「アップデート」を押すとゲームを終了し、インストーラーを起動します。", ko_KR = "BetterGameExperience 사전 릴리스 {1}을(를) 사용할 수 있습니다(설치된 버전: {2}).[NEWLINE][NEWLINE]테스트 버전입니다. 설치 프로그램에서 \"사전 릴리스\"가 선택되어 있어 받게 되었습니다.[NEWLINE][NEWLINE]\"업데이트\"를 누르면 게임을 닫고 설치 프로그램을 실행합니다.", pl_PL = "Dostępna jest wersja testowa {1} BetterGameExperience (zainstalowana: {2}).[NEWLINE][NEWLINE]To wersja testowa: otrzymujesz ją, ponieważ w instalatorze zaznaczone jest pole „Wersja testowa”.[NEWLINE][NEWLINE]„Aktualizuj” zamyka grę i uruchamia instalator.", pt_BR = "A versão de teste {1} do BetterGameExperience está disponível (instalada: {2}).[NEWLINE][NEWLINE]É uma versão de teste: você a recebe porque a caixa \"Versão de teste\" está marcada no instalador.[NEWLINE][NEWLINE]\"Atualizar\" fecha o jogo e abre o instalador.", ru_RU = "Доступна тестовая версия BetterGameExperience {1} (установлена: {2}).[NEWLINE][NEWLINE]Это тестовая версия: вы получаете её, потому что в установщике отмечен флажок «Тестовые версии».[NEWLINE][NEWLINE]«Обновить» закрывает игру и запускает установщик.", zh_Hans_CN = "BetterGameExperience 预发布版本 {1} 已可用（已安装：{2}）。[NEWLINE][NEWLINE]这是测试版本：你收到它是因为安装程序中勾选了“预发布版本”。[NEWLINE][NEWLINE]“更新”会关闭游戏并启动安装程序。" },
	LOC_BGD_MAJ_TEXTE_RELEASE = { en_US = "BetterGameExperience release {1} is available (installed: {2}).[NEWLINE][NEWLINE]\"Update\" closes the game and starts the installer.", fr_FR = "La release {1} de BetterGameExperience est disponible (installée : {2}).[NEWLINE][NEWLINE]« Mettre à jour » ferme le jeu et lance l'installeur.", de_DE = "BetterGameExperience-Version {1} ist verfügbar (installiert: {2}).[NEWLINE][NEWLINE]„Aktualisieren“ schließt das Spiel und startet das Installationsprogramm.", es_ES = "La versión {1} de BetterGameExperience está disponible (instalada: {2}).[NEWLINE][NEWLINE]«Actualizar» cierra el juego e inicia el instalador.", it_IT = "La versione {1} di BetterGameExperience è disponibile (installata: {2}).[NEWLINE][NEWLINE]\"Aggiorna\" chiude il gioco e avvia il programma di installazione.", ja_JP = "BetterGameExperience のリリース {1} が利用可能です (インストール済み: {2})。[NEWLINE][NEWLINE]「アップデート」を押すとゲームを終了し、インストーラーを起動します。", ko_KR = "BetterGameExperience 릴리스 {1}을(를) 사용할 수 있습니다(설치된 버전: {2}).[NEWLINE][NEWLINE]\"업데이트\"를 누르면 게임을 닫고 설치 프로그램을 실행합니다.", pl_PL = "Dostępna jest wersja {1} BetterGameExperience (zainstalowana: {2}).[NEWLINE][NEWLINE]„Aktualizuj” zamyka grę i uruchamia instalator.", pt_BR = "A versão {1} do BetterGameExperience está disponível (instalada: {2}).[NEWLINE][NEWLINE]\"Atualizar\" fecha o jogo e abre o instalador.", ru_RU = "Доступен выпуск BetterGameExperience {1} (установлен: {2}).[NEWLINE][NEWLINE]«Обновить» закрывает игру и запускает установщик.", zh_Hans_CN = "BetterGameExperience 版本 {1} 已可用（已安装：{2}）。[NEWLINE][NEWLINE]“更新”会关闭游戏并启动安装程序。" },
	LOC_BGD_MAJ_TITRE_PRERELEASE = { en_US = "BetterGameExperience: new pre-release", fr_FR = "BetterGameExperience : nouvelle pré-release", de_DE = "BetterGameExperience: neue Vorabversion", es_ES = "BetterGameExperience: nueva versión preliminar", it_IT = "BetterGameExperience: nuova versione di prova", ja_JP = "BetterGameExperience: 新しいプレリリース", ko_KR = "BetterGameExperience: 새 사전 릴리스", pl_PL = "BetterGameExperience: nowa wersja testowa", pt_BR = "BetterGameExperience: nova versão de teste", ru_RU = "BetterGameExperience: новая тестовая версия", zh_Hans_CN = "BetterGameExperience：新的预发布版本" },
	LOC_BGD_MAJ_TITRE_RELEASE = { en_US = "BetterGameExperience: new release", fr_FR = "BetterGameExperience : nouvelle release", de_DE = "BetterGameExperience: neue Version", es_ES = "BetterGameExperience: nueva versión", it_IT = "BetterGameExperience: nuova versione", ja_JP = "BetterGameExperience: 新しいリリース", ko_KR = "BetterGameExperience: 새 릴리스", pl_PL = "BetterGameExperience: nowa wersja", pt_BR = "BetterGameExperience: nova versão", ru_RU = "BetterGameExperience: новый выпуск", zh_Hans_CN = "BetterGameExperience：新版本" },
	LOC_BGD_NOTIF_AIDE = { en_US = "Clears the notifications you can dismiss yourself (deals and pending choices stay).", fr_FR = "Efface les notifications qu'on peut fermer soi-même (les accords et les choix à faire restent).", de_DE = "Löscht die Benachrichtigungen, die Sie selbst schließen können (Abkommen und offene Entscheidungen bleiben).", es_ES = "Borra las notificaciones que puedes cerrar tú mismo (los acuerdos y las decisiones pendientes se quedan).", it_IT = "Cancella le notifiche che puoi chiudere da solo (gli accordi e le scelte da fare restano).", ja_JP = "自分で閉じられる通知を消去します (取引と未決の選択は残ります)。", ko_KR = "직접 닫을 수 있는 알림을 지웁니다(거래와 남은 선택은 그대로 둡니다).", pl_PL = "Czyści powiadomienia, które możesz zamknąć sam (umowy i oczekujące wybory zostają).", pt_BR = "Limpa as notificações que você pode fechar sozinho (os acordos e as escolhas pendentes ficam).", ru_RU = "Очищает уведомления, которые вы можете закрыть сами (сделки и ожидающие решения остаются).", zh_Hans_CN = "清除你能自行关闭的通知（交易和待做的选择会保留）。" },
	LOC_BGD_OPTION_INDICATEURS_AIDE = { en_US = "Hides BetterGameExperience's advanced indicators for every player: science and culture already put in and total cost of the current technology and civic (x/y), science and culture kept in excess (+z), and the production stored by cities. Off by default.", fr_FR = "Masque pour tous les joueurs les indicateurs avancés de BetterGameExperience : science et culture déjà placées et coût total de la technologie et du dogme en cours (x/y), science et culture gardées en excédent (+z), et production gardée en réserve par les villes. Décochée par défaut.", de_DE = "Blendet die erweiterten Anzeigen von BetterGameExperience für alle Spieler aus: bereits investierte Wissenschaft und Kultur sowie Gesamtkosten der aktuellen Technologie und Ausrichtung (x/y), überschüssig gespeicherte Wissenschaft und Kultur (+z) und die von Städten gespeicherte Produktion. Standardmäßig aus.", es_ES = "Oculta a todos los jugadores los indicadores avanzados de BetterGameExperience: ciencia y cultura ya invertidas y coste total de la tecnología y el principio actuales (x/y), ciencia y cultura guardadas como excedente (+z), y la producción que guardan las ciudades. Desactivada por defecto.", it_IT = "Nasconde a tutti i giocatori gli indicatori avanzati di BetterGameExperience: scienza e cultura già investite e costo totale della tecnologia e del civismo in corso (x/y), scienza e cultura conservate in eccedenza (+z), e la produzione conservata dalle città. Disattivata per impostazione predefinita.", ja_JP = "全プレイヤーに対して BetterGameExperience の詳細インジケーターを非表示にします: 研究中のテクノロジーと社会制度に投入済みの科学力・文化力と総コスト (x/y)、超過分として保持された科学力・文化力 (+z)、都市が蓄えている生産力。既定ではオフ。", ko_KR = "모든 플레이어에게 BetterGameExperience의 고급 표시를 숨깁니다: 현재 기술과 사회 제도에 이미 투입된 과학과 문화 및 총비용(x/y), 초과분으로 남은 과학과 문화(+z), 도시가 비축한 생산력. 기본값은 꺼짐입니다.", pl_PL = "Ukrywa przed wszystkimi graczami zaawansowane wskaźniki BetterGameExperience: nauka i kultura już włożone oraz całkowity koszt bieżącej technologii i idei (x/y), nauka i kultura zachowane jako nadwyżka (+z) oraz produkcja zachowana przez miasta. Domyślnie wyłączone.", pt_BR = "Oculta de todos os jogadores os indicadores avançados do BetterGameExperience: ciência e cultura já investidas e custo total da tecnologia e do cívico atuais (x/y), ciência e cultura guardadas como excedente (+z), e a produção guardada pelas cidades. Desativada por padrão.", ru_RU = "Скрывает от всех игроков расширенные индикаторы BetterGameExperience: уже вложенные наука и культура и полная стоимость текущей технологии и цивика (x/y), наука и культура, сохранённые в избытке (+z), и производство, сохранённое городами. По умолчанию выключено.", zh_Hans_CN = "为所有玩家隐藏 BetterGameExperience 的高级指示：当前科技与市政已投入的科技值、文化值及总花费 (x/y)，作为溢出保留的科技值与文化值 (+z)，以及城市储存的生产力。默认关闭。" },
	LOC_BGD_OPTION_PARTIE_AIDE = { en_US = "Every player starts and ends their turn at the same moment. At the start of the turn, everyone waits until all players have finished loading: you can look at the map, but orders are held and the turn timer does not run. At the end, when the host's turn timer runs out, the turn ends for everyone, even if their own timer still shows time left. Every player needs BetterGameExperience, at the same version. Replaces MPH's turn synchronisation, which is turned off.", fr_FR = "Tous les joueurs commencent et finissent leur tour au même instant. Au début du tour, chacun attend que tous aient fini de charger : on peut regarder la carte, mais les ordres sont retenus et le minuteur ne tourne pas. À la fin, quand le minuteur de l'hôte arrive à zéro, le tour se termine pour tout le monde, même si son minuteur affiche encore du temps. Il faut que tous les joueurs aient BetterGameExperience, à la même version. Remplace la synchronisation du tour de MPH, qui est coupée.", de_DE = "Alle Spieler beginnen und beenden ihre Runde im selben Moment. Zu Rundenbeginn warten alle, bis jeder fertig geladen hat: Man kann die Karte ansehen, aber Befehle werden zurückgehalten und der Rundentimer läuft nicht. Am Ende, wenn der Timer des Hosts abläuft, endet die Runde für alle, auch wenn der eigene Timer noch Zeit anzeigt. Alle Spieler brauchen BetterGameExperience in derselben Version. Ersetzt die Rundensynchronisation von MPH, die abgeschaltet wird.", es_ES = "Todos los jugadores empiezan y terminan su turno en el mismo instante. Al principio del turno, cada uno espera a que todos hayan terminado de cargar: se puede mirar el mapa, pero las órdenes se retienen y el temporizador no corre. Al final, cuando el temporizador del anfitrión llega a cero, el turno termina para todos, aunque su temporizador aún muestre tiempo. Todos los jugadores necesitan BetterGameExperience, en la misma versión. Sustituye la sincronización de turno de MPH, que se desactiva.", it_IT = "Tutti i giocatori iniziano e finiscono il turno nello stesso istante. All'inizio del turno, ciascuno aspetta che tutti abbiano finito di caricare: si può guardare la mappa, ma gli ordini vengono trattenuti e il timer non scorre. Alla fine, quando il timer dell'host arriva a zero, il turno finisce per tutti, anche se il proprio timer mostra ancora del tempo. Tutti i giocatori devono avere BetterGameExperience, nella stessa versione. Sostituisce la sincronizzazione del turno di MPH, che viene disattivata.", ja_JP = "全プレイヤーが同時にターンを開始し、同時に終了します。ターン開始時は全員の読み込みが終わるまで待機します。マップは見られますが、命令は保留され、ターンタイマーは進みません。終了時は、ホストのタイマーがゼロになると、自分のタイマーに時間が残っていても全員のターンが終わります。全プレイヤーが同じバージョンの BetterGameExperience を持っている必要があります。MPH のターン同期は無効になり、これに置き換わります。", ko_KR = "모든 플레이어가 같은 순간에 턴을 시작하고 끝냅니다. 턴이 시작되면 모두가 불러오기를 마칠 때까지 기다립니다. 지도는 볼 수 있지만 명령은 보류되고 턴 타이머는 멈춰 있습니다. 턴이 끝날 때는 호스트의 타이머가 0이 되면, 자신의 타이머에 시간이 남아 있어도 모두의 턴이 끝납니다. 모든 플레이어에게 같은 버전의 BetterGameExperience가 필요합니다. MPH의 턴 동기화를 대체하며, 그 기능은 꺼집니다.", pl_PL = "Wszyscy gracze zaczynają i kończą turę w tej samej chwili. Na początku tury każdy czeka, aż wszyscy skończą wczytywanie: można oglądać mapę, ale rozkazy są wstrzymane, a zegar tury nie biegnie. Na końcu, gdy zegar hosta dojdzie do zera, tura kończy się dla wszystkich, nawet jeśli własny zegar pokazuje jeszcze czas. Wszyscy gracze muszą mieć BetterGameExperience w tej samej wersji. Zastępuje synchronizację tury z MPH, która zostaje wyłączona.", pt_BR = "Todos os jogadores começam e terminam o turno no mesmo instante. No início do turno, cada um espera que todos terminem de carregar: dá para olhar o mapa, mas as ordens ficam retidas e o cronômetro não corre. No final, quando o cronômetro do anfitrião chega a zero, o turno termina para todos, mesmo que o próprio cronômetro ainda mostre tempo. Todos os jogadores precisam ter o BetterGameExperience, na mesma versão. Substitui a sincronização de turno do MPH, que é desativada.", ru_RU = "Все игроки начинают и заканчивают ход в один и тот же момент. В начале хода каждый ждёт, пока все закончат загрузку: можно смотреть карту, но приказы задерживаются, а таймер хода не идёт. В конце, когда таймер хоста доходит до нуля, ход заканчивается для всех, даже если на своём таймере ещё осталось время. Всем игрокам нужен BetterGameExperience одной и той же версии. Заменяет синхронизацию хода MPH, которая отключается.", zh_Hans_CN = "所有玩家在同一时刻开始和结束回合。回合开始时，每个人都要等所有人加载完毕：可以查看地图，但指令会被暂缓，回合计时器也不会走。回合结束时，当主机的计时器归零，所有人的回合都会结束，即使自己的计时器还显示有剩余时间。所有玩家都需要安装相同版本的 BetterGameExperience。取代 MPH 的回合同步，该功能会被关闭。" },
	LOC_BGD_OPT_ACTIF_AIDE = { en_US = "Turns off all GameCore proxy changes at once, without uninstalling it: the game behaves as without the proxy. The other settings are kept, and this tab stays available to turn it back on.", fr_FR = "Désactive d'un coup tous les changements du proxy de GameCore, sans le désinstaller : le jeu se comporte comme sans proxy. Les autres réglages sont gardés, et cet onglet reste là pour le réactiver.", de_DE = "Schaltet alle Änderungen des GameCore-Proxys auf einmal ab, ohne ihn zu deinstallieren: Das Spiel verhält sich wie ohne Proxy. Die anderen Einstellungen bleiben erhalten, und dieser Reiter bleibt verfügbar, um ihn wieder einzuschalten.", es_ES = "Desactiva de una vez todos los cambios del proxy de GameCore, sin desinstalarlo: el juego se comporta como sin proxy. Los demás ajustes se conservan, y esta pestaña sigue disponible para volver a activarlo.", it_IT = "Disattiva in un colpo solo tutte le modifiche del proxy di GameCore, senza disinstallarlo: il gioco si comporta come senza proxy. Le altre impostazioni vengono conservate, e questa scheda resta disponibile per riattivarlo.", ja_JP = "GameCore プロキシによる変更を、アンインストールせずにすべて一度に無効にします。ゲームはプロキシがない場合と同じように動作します。他の設定は保持され、このタブから再び有効にできます。", ko_KR = "GameCore 프록시의 모든 변경을 제거하지 않고 한 번에 끕니다. 게임은 프록시가 없는 것처럼 동작합니다. 다른 설정은 유지되며, 이 탭에서 다시 켤 수 있습니다.", pl_PL = "Wyłącza naraz wszystkie zmiany proxy GameCore, bez odinstalowywania go: gra działa tak, jak bez proxy. Pozostałe ustawienia są zachowane, a ta karta pozostaje dostępna, aby je ponownie włączyć.", pt_BR = "Desativa de uma vez todas as mudanças do proxy do GameCore, sem desinstalá-lo: o jogo se comporta como sem o proxy. As outras configurações são mantidas, e esta aba continua disponível para reativá-lo.", ru_RU = "Отключает сразу все изменения прокси GameCore, не удаляя его: игра ведёт себя так, как без прокси. Остальные настройки сохраняются, а эта вкладка остаётся доступной, чтобы снова его включить.", zh_Hans_CN = "一次性关闭 GameCore 代理的所有改动，但不卸载它：游戏的表现与没有代理时相同。其他设置会保留，此标签页也仍然可用，以便重新开启。" },
	LOC_BGD_OPT_ACTIF_NOM = { en_US = "BetterGameExperience proxies", fr_FR = "Proxys BetterGameExperience", de_DE = "BetterGameExperience-Proxys", es_ES = "Proxies de BetterGameExperience", it_IT = "Proxy di BetterGameExperience", ja_JP = "BetterGameExperience プロキシ", ko_KR = "BetterGameExperience 프록시", pl_PL = "Proxy BetterGameExperience", pt_BR = "Proxies do BetterGameExperience", ru_RU = "Прокси BetterGameExperience", zh_Hans_CN = "BetterGameExperience 代理" },
	LOC_BGD_OPT_AFFICHER_AVANCEES = { en_US = "Show advanced options", fr_FR = "Afficher les options avancées", de_DE = "Erweiterte Optionen anzeigen", es_ES = "Mostrar las opciones avanzadas", it_IT = "Mostra le opzioni avanzate", ja_JP = "詳細オプションを表示", ko_KR = "고급 옵션 표시", pl_PL = "Pokaż opcje zaawansowane", pt_BR = "Mostrar as opções avançadas", ru_RU = "Показать дополнительные настройки", zh_Hans_CN = "显示高级选项" },
	LOC_BGD_OPT_AMELIORATIONS_AIDE = { en_US = "Speeds up the question \"can this player build this improvement?\", asked millions of times per turn by the AI. Same result as the game, verified with no difference.", fr_FR = "Accélère la question « ce joueur peut-il construire cette amélioration ? », posée des millions de fois par passage de tour par l'IA. Même résultat que le jeu, vérifié sans aucun écart.", de_DE = "Beschleunigt die Frage „Kann dieser Spieler diese Modernisierung bauen?“, die die KI millionenfach pro Runde stellt. Gleiches Ergebnis wie das Spiel, ohne jede Abweichung überprüft.", es_ES = "Acelera la pregunta «¿puede este jugador construir esta mejora?», que la IA hace millones de veces por turno. Mismo resultado que el juego, verificado sin ninguna diferencia.", it_IT = "Accelera la domanda \"questo giocatore può costruire questo miglioramento?\", posta milioni di volte per turno dall'IA. Stesso risultato del gioco, verificato senza alcuna differenza.", ja_JP = "AI が1ターンに何百万回も行う「このプレイヤーはこの施設を建設できるか?」という判定を高速化します。結果はゲームと同じで、差異がないことを検証済みです。", ko_KR = "AI가 턴마다 수백만 번 묻는 \"이 플레이어가 이 시설을 건설할 수 있는가?\"라는 판정을 빠르게 합니다. 결과는 게임과 같으며, 차이가 없음을 검증했습니다.", pl_PL = "Przyspiesza pytanie „czy ten gracz może zbudować to ulepszenie?”, zadawane przez SI miliony razy na turę. Ten sam wynik co w grze, sprawdzony bez żadnej różnicy.", pt_BR = "Acelera a pergunta \"este jogador pode construir esta melhoria?\", feita milhões de vezes por turno pela IA. Mesmo resultado do jogo, verificado sem nenhuma diferença.", ru_RU = "Ускоряет вопрос «может ли этот игрок построить это улучшение?», который ИИ задаёт миллионы раз за ход. Тот же результат, что и в игре, проверено без единого расхождения.", zh_Hans_CN = "加速“该玩家能否建造此改良设施？”这一判断，AI 每回合要问数百万次。结果与游戏相同，已验证无任何差异。" },
	LOC_BGD_OPT_AMELIORATIONS_NOM = { en_US = "Buildable improvements cache", fr_FR = "Cache des améliorations constructibles", de_DE = "Cache für baubare Modernisierungen", es_ES = "Caché de mejoras construibles", it_IT = "Cache dei miglioramenti costruibili", ja_JP = "建設可能な施設のキャッシュ", ko_KR = "건설 가능한 시설 캐시", pl_PL = "Pamięć podręczna możliwych ulepszeń", pt_BR = "Cache de melhorias construíveis", ru_RU = "Кэш доступных улучшений", zh_Hans_CN = "可建造改良设施缓存" },
	LOC_BGD_OPT_AVERT_PARTIE = { en_US = "These are the settings of the BetterGameExperience proxies (rollover_proxy.cfg). They will take effect when the next game starts.", fr_FR = "Ces réglages sont ceux des proxys BetterGameExperience (rollover_proxy.cfg). Ils prendront effet au lancement de la prochaine partie.", de_DE = "Dies sind die Einstellungen der BetterGameExperience-Proxys (rollover_proxy.cfg). Sie wirken ab dem Start der nächsten Partie.", es_ES = "Estos son los ajustes de los proxies de BetterGameExperience (rollover_proxy.cfg). Surtirán efecto al iniciar la próxima partida.", it_IT = "Queste sono le impostazioni dei proxy di BetterGameExperience (rollover_proxy.cfg). Avranno effetto all'avvio della prossima partita.", ja_JP = "これは BetterGameExperience プロキシの設定 (rollover_proxy.cfg) です。次のゲームの開始時に反映されます。", ko_KR = "BetterGameExperience 프록시의 설정(rollover_proxy.cfg)입니다. 다음 게임을 시작할 때 적용됩니다.", pl_PL = "To są ustawienia proxy BetterGameExperience (rollover_proxy.cfg). Zaczną działać przy uruchomieniu następnej rozgrywki.", pt_BR = "Estas são as configurações dos proxies do BetterGameExperience (rollover_proxy.cfg). Elas terão efeito ao iniciar a próxima partida.", ru_RU = "Это настройки прокси BetterGameExperience (rollover_proxy.cfg). Они вступят в силу при запуске следующей партии.", zh_Hans_CN = "这些是 BetterGameExperience 代理的设置（rollover_proxy.cfg）。将在下一局游戏开始时生效。" },
	LOC_BGD_OPT_AVERT_REDEMARRAGE = { en_US = "These are the settings of the BetterGameExperience proxies (rollover_proxy.cfg). A game has already been started: they will only take effect after restarting the game.", fr_FR = "Ces réglages sont ceux des proxys BetterGameExperience (rollover_proxy.cfg). Une partie a déjà été lancée : ils ne prendront effet qu'au prochain redémarrage du jeu.", de_DE = "Dies sind die Einstellungen der BetterGameExperience-Proxys (rollover_proxy.cfg). Es wurde bereits eine Partie gestartet: Sie wirken erst nach einem Neustart des Spiels.", es_ES = "Estos son los ajustes de los proxies de BetterGameExperience (rollover_proxy.cfg). Ya se ha iniciado una partida: solo surtirán efecto tras reiniciar el juego.", it_IT = "Queste sono le impostazioni dei proxy di BetterGameExperience (rollover_proxy.cfg). Una partita è già stata avviata: avranno effetto solo dopo il riavvio del gioco.", ja_JP = "これは BetterGameExperience プロキシの設定 (rollover_proxy.cfg) です。すでにゲームが開始されているため、ゲームを再起動するまで反映されません。", ko_KR = "BetterGameExperience 프록시의 설정(rollover_proxy.cfg)입니다. 이미 게임이 시작되었으므로 게임을 다시 시작한 뒤에 적용됩니다.", pl_PL = "To są ustawienia proxy BetterGameExperience (rollover_proxy.cfg). Rozgrywka została już uruchomiona: zaczną działać dopiero po ponownym uruchomieniu gry.", pt_BR = "Estas são as configurações dos proxies do BetterGameExperience (rollover_proxy.cfg). Uma partida já foi iniciada: elas só terão efeito depois de reiniciar o jogo.", ru_RU = "Это настройки прокси BetterGameExperience (rollover_proxy.cfg). Партия уже была запущена: они вступят в силу только после перезапуска игры.", zh_Hans_CN = "这些是 BetterGameExperience 代理的设置（rollover_proxy.cfg）。已经开始过一局游戏：只有重启游戏后才会生效。" },
