	LOC_BGD_OPT_CHOIX_MESURE = { en_US = "Measure only (diagnostic)", fr_FR = "Mesure seulement (diagnostic)", de_DE = "Nur messen (Diagnose)", es_ES = "Solo medir (diagnóstico)", it_IT = "Solo misurazione (diagnostica)", ja_JP = "計測のみ (診断)", ko_KR = "측정만 (진단)", pl_PL = "Tylko pomiar (diagnostyka)", pt_BR = "Apenas medir (diagnóstico)", ru_RU = "Только измерение (диагностика)", zh_Hans_CN = "仅测量（诊断）" },
