	LOC_BGD_OPT_CREDITS_AUTEURS_BRS = { en_US = "{1}; original Units and Deals tabs: {2}; thanks: {3}", fr_FR = "{1} ; onglets Unités et Accords d'origine : {2} ; remerciements : {3}", de_DE = "{1}; ursprüngliche Reiter Einheiten und Abkommen: {2}; Dank an: {3}", es_ES = "{1}; pestañas originales Unidades y Acuerdos: {2}; agradecimientos: {3}", it_IT = "{1}; schede originali Unità e Accordi: {2}; ringraziamenti: {3}", ja_JP = "{1}、元のユニット・取引タブ: {2}、謝辞: {3}", ko_KR = "{1}; 원래 유닛·거래 탭: {2}; 감사: {3}", pl_PL = "{1}; oryginalne karty Jednostki i Umowy: {2}; podziękowania: {3}", pt_BR = "{1}; abas originais Unidades e Acordos: {2}; agradecimentos: {3}", ru_RU = "{1}; исходные вкладки «Отряды» и «Сделки»: {2}; благодарности: {3}", zh_Hans_CN = "{1}；原始单位和交易标签页：{2}；鸣谢：{3}" },
