	LOC_BGD_OPT_REINIT_TEXTE = { en_US = "Reset all BetterGameExperience settings to their default values?", fr_FR = "Réinitialiser tous les réglages de BetterGameExperience à leur valeur par défaut ?", de_DE = "Alle Einstellungen von BetterGameExperience auf ihre Standardwerte zurücksetzen?", es_ES = "¿Restablecer todos los ajustes de BetterGameExperience a sus valores predeterminados?", it_IT = "Ripristinare tutte le impostazioni di BetterGameExperience ai valori predefiniti?", ja_JP = "BetterGameExperience のすべての設定を既定値に戻しますか?", ko_KR = "BetterGameExperience의 모든 설정을 기본값으로 되돌리시겠습니까?", pl_PL = "Przywrócić wszystkie ustawienia BetterGameExperience do wartości domyślnych?", pt_BR = "Restaurar todos os ajustes do BetterGameExperience para os valores padrão?", ru_RU = "Вернуть все настройки BetterGameExperience к значениям по умолчанию?", zh_Hans_CN = "要将 BetterGameExperience 的所有设置恢复为默认值吗？" },
	LOC_BGD_OPT_RENDEMENTS_AIDE = { en_US = "Remembers tile yields during the AI's parallel computations, while the map cannot change.", fr_FR = "Mémorise le rendement des cases pendant les calculs parallèles de l'IA, où la carte ne peut pas changer.", de_DE = "Merkt sich die Erträge der Felder während der parallelen Berechnungen der KI, in denen sich die Karte nicht ändern kann.", es_ES = "Memoriza el rendimiento de las casillas durante los cálculos paralelos de la IA, mientras el mapa no puede cambiar.", it_IT = "Memorizza la resa delle caselle durante i calcoli paralleli dell'IA, mentre la mappa non può cambiare.", ja_JP = "マップが変化しない AI の並列計算の間、タイルの産出量を記憶します。", ko_KR = "지도가 바뀔 수 없는 AI의 병렬 계산 동안 타일 산출량을 기억합니다.", pl_PL = "Zapamiętuje plony pól podczas równoległych obliczeń SI, gdy mapa nie może się zmienić.", pt_BR = "Memoriza o rendimento dos hexágonos durante os cálculos paralelos da IA, enquanto o mapa não pode mudar.", ru_RU = "Запоминает доход клеток во время параллельных расчётов ИИ, пока карта не может измениться.", zh_Hans_CN = "在 AI 并行计算期间（地图不会变化）记住单元格的产出。" },
	LOC_BGD_OPT_RENDEMENTS_NOM = { en_US = "Tile yield memory for the AI", fr_FR = "Mémoire des rendements de cases pour l'IA", de_DE = "Gespeicherte Feld-Erträge für die KI", es_ES = "Memoria de rendimientos de casillas para la IA", it_IT = "Memoria delle rese delle caselle per l'IA", ja_JP = "AI 用のタイル産出量の記憶", ko_KR = "AI용 타일 산출량 기억", pl_PL = "Zapamiętywanie plonów pól dla SI", pt_BR = "Memória dos rendimentos dos hexágonos para a IA", ru_RU = "Запоминание доходов клеток для ИИ", zh_Hans_CN = "为 AI 记忆单元格产出" },
	LOC_BGD_OPT_SANS_NATIVES = { en_US = "Startup proxy functions missing: settings can be neither read nor saved.", fr_FR = "Fonctions du proxy de démarrage absentes : les réglages ne peuvent être ni lus ni enregistrés.", de_DE = "Funktionen des Start-Proxys fehlen: Die Einstellungen können weder gelesen noch gespeichert werden.", es_ES = "Faltan las funciones del proxy de inicio: los ajustes no se pueden leer ni guardar.", it_IT = "Funzioni del proxy di avvio mancanti: le impostazioni non possono essere né lette né salvate.", ja_JP = "起動プロキシの機能が見つかりません。設定を読み込むことも保存することもできません。", ko_KR = "시작 프록시의 기능이 없습니다. 설정을 읽거나 저장할 수 없습니다.", pl_PL = "Brak funkcji proxy startowego: ustawień nie można ani odczytać, ani zapisać.", pt_BR = "Funções do proxy de inicialização ausentes: as configurações não podem ser lidas nem salvas.", ru_RU = "Нет функций прокси запуска: настройки нельзя ни прочитать, ни сохранить.", zh_Hans_CN = "缺少启动代理的功能：无法读取或保存设置。" },
