	LOC_BGD_PINGS_HELP = { en_US = "Hold X over the map and release toward a call. Teammates and spectators receive it when all players have the same BGE lobby version.", fr_FR = "Maintenez X sur la carte et relâchez dans la direction du signal. Vos alliés et les spectateurs le reçoivent si tous les joueurs ont la même version de salon BGE.", de_DE = "X auf der Karte gedrückt halten und in Richtung eines Signals loslassen. Verbündete und Zuschauer empfangen es, wenn alle dieselbe BGE-Lobbyversion haben.", es_ES = "Mantén X sobre el mapa y suelta en la dirección de la señal. Los aliados y espectadores la reciben si todos usan la misma versión de sala de BGE.", it_IT = "Tieni premuto X sulla mappa e rilascia nella direzione del segnale. Alleati e spettatori lo ricevono se tutti hanno la stessa versione della lobby BGE.", ja_JP = "マップ上でXを押したまま、合図の方向に動かして離します。全員のBGEロビーバージョンが一致すると、味方と観戦者に届きます。", ko_KR = "지도에서 X를 누른 채 원하는 신호 방향으로 움직인 뒤 놓으세요. 모두 같은 BGE 로비 버전을 사용하면 팀원과 관전자가 신호를 받습니다.", pl_PL = "Przytrzymaj X nad mapą, przesuń kursor w kierunku sygnału i puść klawisz. Sojusznicy i obserwatorzy otrzymają sygnał, jeśli wszyscy mają tę samą wersję lobby BGE.", pt_BR = "Segure X sobre o mapa e solte na direção do sinal. Aliados e espectadores recebem o sinal quando todos usam a mesma versão de sala do BGE.", ru_RU = "Зажмите X над картой, переместите курсор в сторону сигнала и отпустите клавишу. Союзники и наблюдатели получат сигнал, если у всех одинаковая версия лобби BGE.", zh_Hans_CN = "在地图上按住 X，朝所需信号的方向移动鼠标后松开。所有人的 BGE 大厅版本相同时，队友和观战者都能收到信号。" },
