	LOC_BGD_RAPPORT_DESCRIPTION = { en_US = "Describe the problem: what happened, when, and what you expected instead.", fr_FR = "Décrivez le problème : ce qui s'est passé, à quel moment, et ce que vous attendiez à la place.", de_DE = "Beschreiben Sie das Problem: was passiert ist, wann, und was Sie stattdessen erwartet haben.", es_ES = "Describe el problema: qué ha pasado, cuándo y qué esperabas en su lugar.", it_IT = "Descrivi il problema: cosa è successo, quando e cosa ti aspettavi invece.", ja_JP = "問題を説明してください：何が起きたか、いつ起きたか、本来どうなるはずだったか。", ko_KR = "문제를 설명해 주세요: 무슨 일이 언제 일어났는지, 원래 어떻게 될 것으로 예상했는지.", pl_PL = "Opisz problem: co się stało, kiedy i czego oczekiwałeś zamiast tego.", pt_BR = "Descreva o problema: o que aconteceu, quando e o que você esperava em vez disso.", ru_RU = "Опишите проблему: что произошло, когда и чего вы ожидали вместо этого.", zh_Hans_CN = "请描述问题：发生了什么、在什么时候，以及你原本期望的结果。" },
