	LOC_BGD_RAPPORT_INFOBULLE = { en_US = "Sends a save, the last autosaves and the game logs to the BetterGameExperience team. In multiplayer, the other players are told in the chat.", fr_FR = "Envoie une sauvegarde, les derniers autosaves et les journaux du jeu à l'équipe de BetterGameExperience. En multijoueur, les autres joueurs sont prévenus dans le chat.", de_DE = "Sendet einen Spielstand, die letzten automatischen Spielstände und die Spielprotokolle an das Team von BetterGameExperience. Im Mehrspielermodus werden die anderen Spieler im Chat informiert.", es_ES = "Envía una partida guardada, los últimos autoguardados y los registros del juego al equipo de BetterGameExperience. En multijugador, se avisa a los demás jugadores en el chat.", it_IT = "Invia un salvataggio, gli ultimi salvataggi automatici e i registri del gioco al team di BetterGameExperience. In multigiocatore, gli altri giocatori vengono avvisati nella chat.", ja_JP = "セーブデータ、最新のオートセーブ、ゲームのログを BetterGameExperience チームに送信します。マルチプレイでは、他のプレイヤーにチャットで知らせます。", ko_KR = "저장 파일, 최근 자동 저장 파일, 게임 로그를 BetterGameExperience 팀에 보냅니다. 멀티플레이에서는 다른 플레이어에게 채팅으로 알립니다.", pl_PL = "Wysyła zapis gry, ostatnie autozapisy i dzienniki gry do zespołu BetterGameExperience. W grze wieloosobowej pozostali gracze są powiadamiani na czacie.", pt_BR = "Envia um jogo salvo, os últimos salvamentos automáticos e os registros do jogo para a equipe do BetterGameExperience. No multijogador, os outros jogadores são avisados no chat.", ru_RU = "Отправляет сохранение, последние автосохранения и журналы игры команде BetterGameExperience. В сетевой игре остальные игроки получают сообщение в чате.", zh_Hans_CN = "向 BetterGameExperience 团队发送一个存档、最近的自动存档和游戏日志。在多人游戏中，会在聊天中通知其他玩家。" },
	LOC_BGD_RAPPORT_LOCAL_ECHEC = { en_US = "The bug report could not be sent. The archive was saved here: {1}. Send it to @goaterino in a private message on Discord.", fr_FR = "Le rapport de bug n'a pas pu être envoyé. L'archive est enregistrée ici : {1}. Envoyez-la à @goaterino en message privé sur Discord.", de_DE = "Der Fehlerbericht konnte nicht gesendet werden. Das Archiv wurde hier gespeichert: {1}. Senden Sie es per Privatnachricht auf Discord an @goaterino.", es_ES = "No se ha podido enviar el informe de error. El archivo se ha guardado aquí: {1}. Envíalo a @goaterino por mensaje privado en Discord.", it_IT = "Non è stato possibile inviare la segnalazione del bug. L'archivio è stato salvato qui: {1}. Invialo a @goaterino in un messaggio privato su Discord.", ja_JP = "バグレポートを送信できませんでした。アーカイブの保存先: {1}。Discord の個人メッセージで @goaterino に送ってください。", ko_KR = "버그 보고서를 보내지 못했습니다. 압축 파일 저장 위치: {1}. Discord 개인 메시지로 @goaterino 님에게 보내 주세요.", pl_PL = "Nie udało się wysłać zgłoszenia błędu. Archiwum zapisano tutaj: {1}. Wyślij je do @goaterino w prywatnej wiadomości na Discordzie.", pt_BR = "Não foi possível enviar o relatório de bug. O arquivo foi salvo aqui: {1}. Envie-o para @goaterino por mensagem privada no Discord.", ru_RU = "Не удалось отправить отчёт об ошибке. Архив сохранён здесь: {1}. Отправьте его @goaterino в личном сообщении в Discord.", zh_Hans_CN = "错误报告未能发送。压缩包已保存到：{1}。请通过 Discord 私信将其发送给 @goaterino。" },
	LOC_BGD_RAPPORT_LOCAL_OK = { en_US = "Bug report sent, number {1}. To add details, send this number to @goaterino in a private message on Discord.", fr_FR = "Rapport de bug envoyé, numéro {1}. Pour ajouter des détails, envoyez ce numéro à @goaterino en message privé sur Discord.", de_DE = "Fehlerbericht gesendet, Nummer {1}. Um Details zu ergänzen, senden Sie diese Nummer per Privatnachricht auf Discord an @goaterino.", es_ES = "Informe de error enviado, número {1}. Para añadir detalles, envía este número a @goaterino por mensaje privado en Discord.", it_IT = "Segnalazione del bug inviata, numero {1}. Per aggiungere dettagli, invia questo numero a @goaterino in un messaggio privato su Discord.", ja_JP = "バグレポートを送信しました（番号 {1}）。詳細を追加するには、この番号を Discord の個人メッセージで @goaterino に送ってください。", ko_KR = "버그 보고서를 보냈습니다(번호 {1}). 자세한 내용을 추가하려면 이 번호를 Discord 개인 메시지로 @goaterino 님에게 보내 주세요.", pl_PL = "Zgłoszenie błędu wysłane, numer {1}. Aby dodać szczegóły, wyślij ten numer do @goaterino w prywatnej wiadomości na Discordzie.", pt_BR = "Relatório de bug enviado, número {1}. Para adicionar detalhes, envie este número para @goaterino por mensagem privada no Discord.", ru_RU = "Отчёт об ошибке отправлен, номер {1}. Чтобы добавить подробности, отправьте этот номер @goaterino в личном сообщении в Discord.", zh_Hans_CN = "错误报告已发送，编号 {1}。如需补充细节，请通过 Discord 私信将此编号发送给 @goaterino。" },
	LOC_BGD_RAPPORT_TEXTE = { en_US = "BetterGameExperience will send its team a save of this moment, the last autosaves and the game logs. Your Windows user name is removed from the logs.", fr_FR = "BetterGameExperience va envoyer à son équipe une sauvegarde de ce moment, les derniers autosaves et les journaux du jeu. Votre nom d'utilisateur Windows est retiré des journaux.", de_DE = "BetterGameExperience sendet seinem Team einen Spielstand dieses Moments, die letzten automatischen Spielstände und die Spielprotokolle. Ihr Windows-Benutzername wird aus den Protokollen entfernt.", es_ES = "BetterGameExperience enviará a su equipo una partida guardada de este momento, los últimos autoguardados y los registros del juego. Tu nombre de usuario de Windows se elimina de los registros.", it_IT = "BetterGameExperience invierà al suo team un salvataggio di questo momento, gli ultimi salvataggi automatici e i registri del gioco. Il tuo nome utente di Windows viene rimosso dai registri.", ja_JP = "BetterGameExperience は、この時点のセーブデータ、最新のオートセーブ、ゲームのログをチームに送信します。Windows のユーザー名はログから削除されます。", ko_KR = "BetterGameExperience가 현재 시점의 저장 파일, 최근 자동 저장 파일, 게임 로그를 팀에 보냅니다. Windows 사용자 이름은 로그에서 제거됩니다.", pl_PL = "BetterGameExperience wyśle swojemu zespołowi zapis z tej chwili, ostatnie autozapisy i dzienniki gry. Twoja nazwa użytkownika Windows zostaje usunięta z dzienników.", pt_BR = "O BetterGameExperience vai enviar à sua equipe um jogo salvo deste momento, os últimos salvamentos automáticos e os registros do jogo. Seu nome de usuário do Windows é removido dos registros.", ru_RU = "BetterGameExperience отправит своей команде сохранение этого момента, последние автосохранения и журналы игры. Ваше имя пользователя Windows удаляется из журналов.", zh_Hans_CN = "BetterGameExperience 将向其团队发送此刻的存档、最近的自动存档和游戏日志。你的 Windows 用户名会从日志中删除。" },
